package com.juicyslew.moonstation14.ms14.atmos.machine.ui.client;

import com.juicyslew.moonstation14.ms14.atmos.machine.AtmosMachineProfile;
import com.juicyslew.moonstation14.ms14.atmos.machine.AtmosMachineSettings;
import com.juicyslew.moonstation14.ms14.atmos.machine.ui.AtmosMachineControlSnapshot;
import com.juicyslew.moonstation14.ms14.ui.model.DraftFieldModel;
import java.math.BigDecimal;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class AtmosMachineClientModelTest {
    private static AtmosMachineControlSnapshot snapshot(AtmosMachineProfile.Kind kind, int id, UUID session, long req,long rev, boolean accepted){
        boolean p=kind==AtmosMachineProfile.Kind.PRESSURE_PUMP, r=kind==AtmosMachineProfile.Kind.VOLUME_PUMP||kind==AtmosMachineProfile.Kind.FILTER, m=kind==AtmosMachineProfile.Kind.MIXER, f=kind==AtmosMachineProfile.Kind.FILTER, t=kind==AtmosMachineProfile.Kind.HEATER||kind==AtmosMachineProfile.Kind.FREEZER;
        var v=new AtmosMachineSettings.Values(rev,Optional.of(false),p||m?Optional.of(100d):Optional.empty(),r?Optional.of(.1):Optional.empty(),m?Optional.of(.25):Optional.empty(),Optional.empty(),t?Optional.of(300d):Optional.empty(),Optional.empty());
        var c=new AtmosMachineControlSnapshot.Controls("profile",kind,true,p||m,r,m,f,t,p||m?4500:0,r?1:0,t?100:0,t?600:0);
        return new AtmosMachineControlSnapshot(id,session,req,accepted,v,c,0,false);
    }
    @Test void capabilitiesAndUnitsCoverSixOrdinaryKinds(){UUID id=UUID.randomUUID();for(var k:List.of(AtmosMachineProfile.Kind.PRESSURE_PUMP,AtmosMachineProfile.Kind.VOLUME_PUMP,AtmosMachineProfile.Kind.MIXER,AtmosMachineProfile.Kind.FILTER,AtmosMachineProfile.Kind.HEATER,AtmosMachineProfile.Kind.FREEZER)){
        var s=snapshot(k,4,id,-1,0,true);var c=s.controls();assertTrue(c.enabled());assertEquals(k==AtmosMachineProfile.Kind.PRESSURE_PUMP||k==AtmosMachineProfile.Kind.MIXER,c.pressure());assertEquals(k==AtmosMachineProfile.Kind.VOLUME_PUMP||k==AtmosMachineProfile.Kind.FILTER,c.rate());assertEquals(k==AtmosMachineProfile.Kind.MIXER,c.mixerRatio());assertEquals(k==AtmosMachineProfile.Kind.FILTER,AtmosMachineClientModel.hasGasSelector(c));assertEquals(k==AtmosMachineProfile.Kind.HEATER||k==AtmosMachineProfile.Kind.FREEZER,c.thermostat());
    }
        assertEquals(.125,AtmosMachineClientModel.canonicalValue(AtmosMachineClientModel.Numeric.RATE_LPS,125));assertEquals(125,AtmosMachineClientModel.displayValue(AtmosMachineClientModel.Numeric.RATE_LPS,.125));assertEquals(75,AtmosMachineClientModel.complementaryPercent(.25));assertEquals("300.00",AtmosMachineClientModel.format(AtmosMachineClientModel.Numeric.THERMOSTAT_K,300));
        var filter=snapshot(AtmosMachineProfile.Kind.FILTER,4,id,-1,0,true);assertTrue(AtmosMachineClientModel.hasGasSelector(filter.controls()));assertEquals("NONE",AtmosMachineClientModel.gasLabel(Optional.empty()));assertTrue(AtmosMachineClientModel.validNumeric(AtmosMachineClientModel.Numeric.THERMOSTAT_K,300.1,snapshot(AtmosMachineProfile.Kind.HEATER,4,id,-1,0,true).controls()));assertFalse(AtmosMachineClientModel.validNumeric(AtmosMachineClientModel.Numeric.THERMOSTAT_K,300.15,snapshot(AtmosMachineProfile.Kind.HEATER,4,id,-1,0,true).controls()));
    }
    @Test void reconciliationIgnoresWrongSessionStaleRevisionAndOldAckButAllowsRejectionAndPreservesPendingOnUnsolicited(){UUID session=UUID.randomUUID();var model=new AtmosMachineClientModel(4,session,"profile");var base=snapshot(AtmosMachineProfile.Kind.PRESSURE_PUMP,4,session,-1,3,true);assertTrue(model.accept(base));model.pending(8);
        assertFalse(model.accept(snapshot(AtmosMachineProfile.Kind.PRESSURE_PUMP,4,UUID.randomUUID(),-1,4,true)));assertFalse(model.accept(snapshot(AtmosMachineProfile.Kind.PRESSURE_PUMP,4,session,-1,2,true)));assertFalse(model.accept(snapshot(AtmosMachineProfile.Kind.PRESSURE_PUMP,4,session,7,4,true)));
        assertTrue(model.accept(snapshot(AtmosMachineProfile.Kind.PRESSURE_PUMP,4,session,-1,4,true)));assertEquals(8,model.pending());assertTrue(model.accept(snapshot(AtmosMachineProfile.Kind.PRESSURE_PUMP,4,session,8,4,false)));assertEquals(-1,model.pending());assertFalse(model.snapshot().accepted());
    }
    @Test void mixerHasTwoEditableIndependentSettings(){var c=snapshot(AtmosMachineProfile.Kind.MIXER,4,UUID.randomUUID(),-1,0,true).controls();assertEquals(List.of(AtmosMachineClientModel.Numeric.PRESSURE_KPA,AtmosMachineClientModel.Numeric.MIXER_PERCENT),AtmosMachineClientModel.numericFields(c));assertEquals(.5,AtmosMachineClientModel.canonicalValue(AtmosMachineClientModel.Numeric.MIXER_PERCENT,50));assertEquals(50,AtmosMachineClientModel.displayValue(AtmosMachineClientModel.Numeric.PRESSURE_KPA,50));}
    @Test void completedAckMayRepeatPeriodicallyAndCannotConsumeNewerPendingOrDraft(){UUID session=UUID.randomUUID();var model=new AtmosMachineClientModel(4,session,"profile");assertTrue(model.accept(snapshot(AtmosMachineProfile.Kind.PRESSURE_PUMP,4,session,-1,0,true)));model.pending(0);assertTrue(model.accept(snapshot(AtmosMachineProfile.Kind.PRESSURE_PUMP,4,session,0,1,true)));assertEquals(-1,model.pending());assertTrue(model.accept(snapshot(AtmosMachineProfile.Kind.PRESSURE_PUMP,4,session,0,1,true)));model.pending(1);assertTrue(model.accept(snapshot(AtmosMachineProfile.Kind.PRESSURE_PUMP,4,session,0,1,true)));assertEquals(1,model.pending());assertFalse(model.accept(snapshot(AtmosMachineProfile.Kind.PRESSURE_PUMP,4,session,2,2,true)));assertFalse(model.accept(snapshot(AtmosMachineProfile.Kind.PRESSURE_PUMP,4,session,-1,2,true)));assertTrue(model.accept(snapshot(AtmosMachineProfile.Kind.PRESSURE_PUMP,4,session,1,2,false)));assertEquals(-1,model.pending());}
     @Test void resizeReflowRetainsModelPendingAndPerFieldDraft(){UUID session=UUID.randomUUID();var owner=new AtmosMachineClientModel(4,session,"profile");var draft=DraftFieldModel.number(8,BigDecimal.ZERO,new BigDecimal("5000"));assertTrue(owner.accept(snapshot(AtmosMachineProfile.Kind.MIXER,4,session,-1,0,true)));draft.snapshot(0,"100.00");draft.edit("200.00");var intent=draft.submit();owner.pending(0);var large=AtmosMachineLayout.forViewport(640,480);var small=AtmosMachineLayout.forViewport(120,90);assertFalse(large.tooSmall());assertTrue(small.tooSmall());assertEquals(0,owner.pending());assertEquals("200.00",draft.draft());assertTrue(owner.accept(snapshot(AtmosMachineProfile.Kind.MIXER,4,session,0,1,true)));assertTrue(draft.resolve(intent.requestId(),1,"200.00",true));}
    @Test void sharedDraftOwnerPreservesUnsolicitedSnapshotThenResolvesRejectionAndTimeout(){var d=DraftFieldModel.number(8,BigDecimal.ZERO,new BigDecimal("1000"));d.snapshot(4,"20.00");d.edit("25.00");var intent=d.submit();assertNotNull(intent);d.snapshot(5,"21.00");assertEquals("25.00",d.draft());assertFalse(d.resolve(intent.requestId()+1,5,"21.00",false));assertTrue(d.resolve(intent.requestId(),5,"21.00",false));assertEquals(DraftFieldModel.State.REJECTED,d.state());d.edit("30.00");var timeout=d.submit();assertNotNull(timeout);assertTrue(d.cancelPending(timeout.requestId()));assertEquals(DraftFieldModel.State.REJECTED,d.state());assertFalse(d.cancelPending(timeout.requestId()));}
}
